import org.gradle.api.Plugin
import org.gradle.api.Project
import org.gradle.kotlin.dsl.dependencies

/**
 * The app side of the Baseline Profile (CLAUDE.md §5): applies the AndroidX Baseline Profile plugin, which
 * compiles the profile committed under `src/release/generated/baselineProfiles/` into release builds, and adds
 * ProfileInstaller so APKs installed from GitHub Releases get the profile too (Play applies it on its own).
 * Apply after `calwp.android.application`. The profile is generated by `:baselineprofile`; see its README.
 */
class BaselineProfileConsumerConventionPlugin : Plugin<Project> {
    override fun apply(target: Project) {
        with(target) {
            pluginManager.apply("androidx.baselineprofile")
            dependencies {
                add("implementation", libs.library("androidx-profileinstaller"))
            }
        }
    }
}
